const PORT = process.env.PORT ? Number(process.env.PORT) : 8080;
const DB_PATH = process.env.DB_PATH || path.join(__dirname, 'workboard.db');

const dbPromise = (async () => {
  const db = await open({ filename: DB_PATH, driver: sqlite3.Database });
  await db.run(`CREATE TABLE IF NOT EXISTS projects (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL)`);
  return db;
})();

async function serveStatic(filePath, res) {
  try {
    const data = await readFile(filePath);
    const ext = path.extname(filePath).toLowerCase();
    const ct = {
      '.html': 'text/html',
      '.js': 'application/javascript',
      '.css': 'text/css'
    }[ext] || 'application/octet-stream';
    res.writeHead(200, { 'Content-Type': ct });
    res.end(data);
  } catch {
    res.writeHead(404);
    res.end('Not found');
  }
}

async function parseJson(req) {
  const chunks = [];
  for await (const chunk of req) { chunks.push(chunk); }
  const body = Buffer.concat(chunks).toString();
  return JSON.parse(body);
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);
  const pathname = url.pathname;

  if (pathname === '/health' && req.method === 'GET') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ status: 'ok' }));
    return;
  }

  if (pathname.startsWith('/api/')) {
    const db = await dbPromise;
    if (pathname === '/api/projects' && req.method === 'GET') {
      const rows = await db.all('SELECT id, name FROM projects ORDER BY id ASC');
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify(rows));
      return;
    }
    if (pathname === '/api/projects' && req.method === 'POST') {
      try {
        const { name } = await parseJson(req);
        const trimmed = typeof name === 'string' ? name.trim() : '';
        if (!trimmed) {
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'Project name is required' }));
          return;
        }
        const result = await db.run('INSERT INTO projects (name) VALUES (?)', trimmed);
        const newProject = { id: result.lastID, name: trimmed };
        res.writeHead(201, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify(newProject));
      } catch (e) {
        res.writeHead(500, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Internal server error' }));
      }
      return;
    }
